SELECT Hc_Code AS hcCode, Hc_Seq AS hcSeq, Hc_Name AS hcName, Hc_RMK AS hcRmk, Hc_ColumNm AS hcColumNm, Hc_Filter AS hcFilter, Hc_SqlFg AS hcSqlFg, Hc_Sql AS hcSql, Hc_Ratio AS hcRatio, Hc_Code1 AS hcCode1, Hc_UpFlag AS hcUpFlag, Hc_RegDt AS hcRegDt FROM I_HelpCD
AND Hc_Code = #{hcCode}
ORDER BY Hc_Seq
